<script setup>
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Button,FrappeUIProvider} from 'frappe-ui'
import {useSession,useScope} from './store'
import {call,consoleAPI,upload} from './api'
import {pages,titles,moduleKey,fmt,cleanFields,laborMatrix} from './domain'
import {docLabel,stateLabel,label} from './labels'
import OpsList from './components/OpsList.vue'
import SchemaForm from './components/SchemaForm.vue'
import PlotMap from './components/PlotMap.vue'
import {queueCapture,queueRows,syncCaptures,reconcileCapture,clearSent} from './offline'
const session=useSession(),scope=useScope(),route=useRoute(),router=useRouter()
const busy=ref(false),error=ref(''),message=ref(''),data=ref(null),doctype=ref(''),list=ref({rows:[],columns:[],has_more:false}),start=ref(0),search=ref(''),sort=ref('modified desc')
const editor=ref(null),schema=ref(null),audit=ref(null),trace=ref(null),dialogBusy=ref(false),reason=ref(''),shift=ref(null),shiftTab=ref('General'),workDialog=ref(null),workActual=reactive({quantity:0,days:0,reason:'',attribution:[]}),material=ref(null),qc=ref(null),overview=ref(null),staff=ref(null),preview=ref(null),orderLines=ref([]),evidence=ref(null),losses=ref(null),productivity=ref(null),importPreview=ref(null),mapData=ref(null),settingsDoc=ref(null),settingsSchema=ref(null),delivery=ref([]),qr=ref(null),outbox=ref([]),outboxOpen=ref(false),online=ref(navigator.onLine)
const page=computed(()=>route.path.slice(1)||'today'),key=computed(()=>moduleKey(page.value)),types=computed(()=>session.modules[key.value]||[])
const nav=computed(()=>pages.filter(([p])=>p==='today'?session.capabilities.home:p==='reports'?session.capabilities.home:!!session.modules[moduleKey(p)]))
const farms=computed(()=>session.farms.filter(f=>!scope.company||f.company===scope.company)),companies=computed(()=>[...new Set(session.farms.map(f=>f.company))]),scopeArgs=computed(()=>scope.query())
const breadcrumb=computed(()=>[scope.company,scope.farm,scope.block,scope.plot].filter(Boolean).join(' › '))
const tabs=['Công việc','Sản lượng','Tổn thất','Vật tư','Nhân sự','QC','Ảnh','Lịch sử thay đổi'],farmTab=ref('Công việc'),tree=ref([])
const fieldEvidence=reactive({latitude:null,longitude:null,gps_accuracy_m:null,photo:null})
const summary=computed(()=>data.value?.farms||[]),tasks=computed(()=>overview.value?.tasks||summary.value.flatMap(f=>f.tasks.map(t=>({...t,farm:f.farm})))||[])
const cards=computed(()=>{const sum=k=>summary.value.reduce((n,f)=>n+Number(f[k]||0),0);return [
 {label:'Việc hoàn thành',value:summary.value.length?summary.value.reduce((n,f)=>n+Number(f.work_completion_percent||0),0)/summary.value.length:null,unit:'%',route:'work'},
 {label:'Thiếu / thừa công',value:sum('labor_gap_workdays'),unit:'công',route:'labor'},
 {label:'Vật tư cần kiểm tra',value:summary.value.reduce((n,f)=>n+(f.outstanding_material?.length||0),0),unit:'dòng nhu cầu',route:'materials'},
 {label:'Dự thu 8 tuần',value:data.value?.forecast?.reduce((n,f)=>n+Number(f.packed_forecast_kg||0),0),unit:'kg',route:'plans'},
 {label:'Thu hoạch',value:sum('harvest_kg'),unit:'kg',route:'harvest'},
 {label:'Buồng hủy',value:sum('cancelled_bunches'),unit:'buồng',route:'losses'},
 {label:'QC đầu vào',value:summary.value.length===1?summary.value[0].incoming_defect_percent:null,unit:'% lỗi · xem chi tiết',route:'incoming-qc'},
 {label:'Thành phẩm',value:sum('finished_kg'),unit:'kg',route:'packhouse'},
 {label:'Phụ phẩm',value:sum('secondary_kg'),unit:'kg',route:'packhouse'},
 {label:'Hao hụt',value:sum('loss_kg'),unit:'kg',route:'packhouse'},
 {label:'Chốt ngày',value:summary.value.filter(f=>!f.closed).length,unit:'nông trường chưa chốt',route:'daily-close'}]})
function newEventID(){return crypto.randomUUID()}
async function run(fn){error.value='';try{return await fn()}catch(e){error.value=e.message;return null}}
function go(path,extra={}){router.push({path:'/'+path,query:scope.query(extra)})}
function updateScope(){start.value=0;router.replace({path:route.path,query:scope.query()})}
async function load(){if(!session.ready)return;busy.value=true;error.value='';preview.value=null;trace.value=null;shift.value=null;overview.value=null;material.value=null;qc.value=null;data.value=null;losses.value=null;await run(async()=>{
 if(['today','reports'].includes(page.value)){data.value=await call(page.value==='reports'?'lotus_farm.reporting.forecast_vintages':'lotus_farm.reporting.dashboard',{from_date:scope.from_date||scope.date,to_date:scope.to_date||scope.date,farm:scope.farm||null,company:scope.company||null});if(page.value==='reports'){productivity.value=await call('lotus_farm.productivity.report',{from_date:scope.from_date||scope.date,to_date:scope.to_date||scope.date,farm:scope.farm||null});delivery.value=scope.farm?await call('lotus_farm.reporting.delivery_progress',{farm:scope.farm}):[]}return}
 if(page.value==='map'){mapData.value=scope.farm?await call('lotus_farm.field.map_data',{farm:scope.farm}):null;return}
 if(page.value==='trace'){trace.value=null;return}
 if(page.value==='admin/settings'){settingsSchema.value=await consoleAPI('schema',{doctype:'Lotus Farm Settings'});settingsDoc.value=await consoleAPI('settings');return}
 if(/^plot\//.test(page.value)){data.value=await call('lotus_farm.reporting.plot_history',{farm_plot:decodeURIComponent(page.value.slice(5))});return}
 if(/^(farm|block)\//.test(page.value)||page.value==='farms'){
  const type=page.value.startsWith('farm/')?'Farm Block':page.value.startsWith('block/')?'Farm Plot':'Farm'
  const id=decodeURIComponent(page.value.split('/')[1]||'')
  tree.value=(await consoleAPI('listing',{doctype:type,farm:type==='Farm Block'?id:scope.farm,block:type==='Farm Plot'?id:scope.block,company:scope.company,start:start.value,length:50}));return
 }
 if(!types.value.includes(doctype.value))doctype.value=types.value[0]||''
 if(!doctype.value)return
 list.value=await consoleAPI('listing',{doctype:doctype.value,...scopeArgs.value,start:start.value,search:search.value,sort:sort.value})
 if(key.value==='daily-close'&&!scope.farm)data.value=await call('lotus_farm.reporting.dashboard',{company:scope.company||null,from_date:scope.date,to_date:scope.date})
 if(scope.farm&&['work','labor'].includes(key.value)){overview.value=await call('lotus_farm.daily_api.daily_overview',{farm:scope.farm,posting_date:scope.date});if(key.value==='labor')staff.value=await call('lotus_farm.field.available_labor',{farm:scope.farm,posting_date:scope.date})}
 if(scope.farm&&key.value==='materials')material.value=await consoleAPI('material_status',{farm:scope.farm,posting_date:scope.date})
 if(key.value==='losses')losses.value=await consoleAPI('loss_analysis',{farm:scope.farm,from_date:scope.from_date||scope.date,to_date:scope.to_date||scope.date})
 if(scope.farm&&key.value==='incoming-qc')qc.value=await consoleAPI('quality_matrix',{farm:scope.farm,posting_date:scope.date})
 });busy.value=false}
async function edit(type,name=null,defaults={}){await run(async()=>{qr.value=null;fieldEvidence.latitude=null;fieldEvidence.longitude=null;fieldEvidence.gps_accuracy_m=null;fieldEvidence.photo=null;schema.value=await consoleAPI('schema',{doctype:type});const doc=name?await consoleAPI('detail',{doctype:type,name}):{doctype:type,...Object.fromEntries(schema.value.fields.filter(f=>f.default!=null).map(f=>[f.fieldname,f.default])),farm:scope.farm,company:scope.company||session.farms.find(f=>f.name===scope.farm)?.company,posting_date:scope.date,harvest_date:scope.date,packing_date:scope.date,received_date:scope.date,...defaults};editor.value=doc;reason.value='';audit.value=null;evidence.value=null;shift.value=null;if(name)evidence.value=await consoleAPI('evidence',{doctype:type,name});if(type==='Packhouse Shift'&&name)shift.value=await consoleAPI('shift_detail',{name})})}
async function save(){dialogBusy.value=true;await run(async()=>{const d=editor.value;editor.value=await consoleAPI('save',{doctype:d.doctype,name:d.name,base_modified:d.modified,values:cleanFields(schema.value,d)},true);message.value='Đã lưu phiếu nháp.';await load()});dialogBusy.value=false}
async function action(which){dialogBusy.value=true;await run(async()=>{editor.value=await consoleAPI('document_action',{doctype:editor.value.doctype,name:editor.value.name,base_modified:editor.value.modified,action:which,reason:reason.value},true);message.value='Đã cập nhật chứng từ.';await load()});dialogBusy.value=false}
async function command(method,args){dialogBusy.value=true;const r=await run(()=>call(method,args,true));dialogBusy.value=false;if(r!=null){message.value='Đã xử lý. '+(r.stock_entry||r.material_request||r.plan||r.batch||r.profile||'');await load();if(editor.value?.name)editor.value=await consoleAPI('detail',{doctype:editor.value.doctype,name:editor.value.name})}return r}
async function showAudit(){audit.value=await run(()=>consoleAPI('audit',{doctype:editor.value.doctype,name:editor.value.name}))}
async function showQR(){qr.value=await run(()=>call('lotus_farm.field.lot_qr',{harvest_lot:editor.value.name}))}
async function traceSearch(){const kind=extra.trace_kind,query=(extra.trace_query||'').trim();if(!query){error.value='Nhập mã cần truy xuất.';return}trace.value=await run(async()=>{if(kind==='Harvest Lot')return {kind,result:await call('lotus_farm.reporting.trace_lot',{harvest_lot:query})};if(kind==='Packout Run')return {kind,result:await call('lotus_farm.reporting.trace_packout',{packout:query})};if(kind==='Farm Plot')return {kind,result:await call('lotus_farm.reporting.plot_history',{farm_plot:query})};return {kind,result:await call('lotus_farm.reporting.trace_item',{item:query,batch:extra.trace_batch||null})}})}
async function saveSettings(){dialogBusy.value=true;await run(async()=>{settingsDoc.value=await consoleAPI('save_settings',{base_token:settingsDoc.value._settings_token,values:cleanFields(settingsSchema.value,settingsDoc.value)},true);message.value='Đã lưu cấu hình.'});dialogBusy.value=false}
async function refreshOutbox(){outbox.value=await queueRows(session.user)}
function locate(){if(!navigator.geolocation){error.value='Thiết bị không hỗ trợ lấy vị trí.';return}navigator.geolocation.getCurrentPosition(p=>{fieldEvidence.latitude=p.coords.latitude;fieldEvidence.longitude=p.coords.longitude;fieldEvidence.gps_accuracy_m=p.coords.accuracy},e=>error.value=e.message,{enableHighAccuracy:true,timeout:12000})}
function capturePayload(){const values={};for(const key of schema.value?.capture_fields||[])if(Object.prototype.hasOwnProperty.call(editor.value,key)&&editor.value[key]!==''&&editor.value[key]!=null)values[key]=editor.value[key];return {client_event_id:editor.value._event_id||(editor.value._event_id=crypto.randomUUID()),farm:scope.farm||editor.value.farm,target_doctype:editor.value.doctype,values,captured_at:new Date().toISOString(),latitude:fieldEvidence.latitude,longitude:fieldEvidence.longitude,gps_accuracy_m:fieldEvidence.gps_accuracy_m}}
async function queueEditor(){if(!schema.value?.capture_fields?.length){error.value='Phiếu này không hỗ trợ nhập hiện trường offline.';return}const event=capturePayload();if(!event.farm){error.value='Chọn nông trường trước.';return}await run(async()=>{await queueCapture(session.user,event,fieldEvidence.photo);await refreshOutbox();message.value='Đã giữ bản ghi trên máy. Khi có mạng bấm Đồng bộ.';editor.value=null})}
async function sendField(){if(!schema.value?.capture_fields?.length)return;const event=capturePayload();if(!event.farm){error.value='Chọn nông trường trước.';return}dialogBusy.value=true;await run(async()=>{if(fieldEvidence.photo){const up=await upload(fieldEvidence.photo);event.photo=up.file_url}const result=await call('lotus_farm.field.capture',event,true);message.value='Đã ghi hiện trường '+result.document;editor.value=null;await load()});dialogBusy.value=false}
async function syncOutbox(){await run(async()=>{const current=await call('lotus_farm.field.session_info');if(current.user!==session.user)throw new Error('Tài khoản đã thay đổi; không gửi hàng chờ của người khác.');await syncCaptures(session.user,{call,upload:file=>upload(file)});await refreshOutbox();message.value='Đã xử lý hàng chờ; bản lỗi vẫn được giữ để kiểm tra.'})}
async function reconcileRow(row){await run(async()=>{let reason='';const status=await call('lotus_farm.field.capture_status',{client_event_id:row.event.client_event_id});if(!status.received){reason=window.prompt('Máy chủ chưa nhận bản này. Nếu muốn bỏ bản nhập sai, ghi lý do; để trống để giữ lại.')||''}await reconcileCapture(session.user,row.key,{call},reason);await refreshOutbox()})}
async function clearSentRows(){await clearSent(session.user);await refreshOutbox()}
function changes(version){try{return JSON.parse(version.data).changed||[]}catch{return []}}
async function showTrace(type,name){trace.value=await run(()=>call(type==='Harvest Lot'?'lotus_farm.reporting.trace_lot':type==='Packout Run'?'lotus_farm.reporting.trace_packout':'lotus_farm.reporting.plot_history',type==='Harvest Lot'?{harvest_lot:name}:type==='Packout Run'?{packout:name}:{farm_plot:name}))}
async function transition(task,state){await command('lotus_farm.console.work_state',{plan:task.plan,line:task.line,state,reason:reason.value})}
function complete(task){workDialog.value=task;workActual.quantity=task.planned_qty;workActual.days=task.allocated_workdays;workActual.reason='';workActual.attribution=[]}
async function finish(){dialogBusy.value=true;await run(async()=>{const t=workDialog.value;await call('lotus_farm.field.capture',{client_event_id:workDialog.value.event_id??=(crypto.randomUUID()),farm:scope.farm,target_doctype:'Daily Work Result',captured_at:new Date().toISOString(),values:{farm_block:t.farm_block,farm_plot:t.farm_plot,crop_cycle:t.crop_cycle,sucker_selection_batch:t.cohort||null,posting_date:scope.date,work_plan:t.plan,work_plan_line:t.line,completed_qty:workActual.quantity,actual_workdays:workActual.days,unfinished_reason:workActual.reason,actual_labor:workActual.attribution.map(a=>{const source=t.allocations.find(r=>r.name===a.allocation);return {employee:source?.employee||null,work_team:source?.employee?null:(source?.work_team||null),actual_workdays:a.days,completed_qty:a.quantity}})}},true);workDialog.value=null;await load()});dialogBusy.value=false}
async function uploadSource(event){const file=event.target.files[0];if(!file)return;const result=await run(()=>upload(file,editor.value.doctype,editor.value.name));if(result)extra.file_url=result.file_url}
async function closePreview(){preview.value=await run(()=>call('lotus_farm.daily_api.preview_close',{farm:scope.farm,posting_date:scope.date}))}
const extra=reactive({warehouse:'',schedule_date:'',file_url:'',crop_cycle:'',base_profile:'',valid_from:'',valid_to:'',sample_from:'',sample_to:'',item:'',quantity:0,sales_order:'',sales_order_item:'',stock_reservation:'',trace_kind:'Harvest Lot',trace_query:'',trace_batch:''})
function typeChanged(){start.value=0;load()}
function pageMore(delta){start.value=Math.max(0,start.value+delta);load()}
async function openHierarchy(row){if(page.value==='farms')go('farm/'+encodeURIComponent(row.name),{farm:row.name,company:row.company});else if(page.value.startsWith('farm/'))go('block/'+encodeURIComponent(row.name),{block:row.name});else go('plot/'+encodeURIComponent(row.name),{plot:row.name})}
onMounted(async()=>{await run(async()=>{await session.load();scope.fromQuery(route.query,session.today);if(scope.farm&&!session.farms.some(f=>f.name===scope.farm)){scope.farm='';scope.block='';scope.plot=''}await refreshOutbox();if(!nav.value.some(([p])=>p===page.value)&&page.value==='today'&&nav.value.length)go(nav.value[0][0]);else await load()});window.addEventListener('online',()=>{online.value=true});window.addEventListener('offline',()=>{online.value=false})})
watch(()=>route.fullPath,()=>{if(session.ready){scope.fromQuery(route.query,session.today);start.value=0;load()}})
</script>

<template><FrappeUIProvider><div class="app-shell"><aside class="sidebar"><a class="brand" href="/lotus/today">◈ <span>LOTUS<small>ĐIỀU HÀNH NÔNG TRƯỜNG</small></span></a><nav><button v-for="[path,label] in nav" :key="path" :class="{active:page===path}" @click="go(path)">{{label}}</button></nav><button class="field-link offline-status" @click="outboxOpen=true">{{online?'Có mạng':'Mất mạng'}} · {{outbox.filter(r=>!['Sent','Discarded'].includes(r.status)).length}} đang chờ</button><button class="field-link offline-status" :disabled="!online" @click="syncOutbox">Đồng bộ hàng chờ</button><a class="field-link" :href="'/assets/lotus_farm/field/index.html'">UI hiện trường dự phòng ↗</a><small>{{session.user}}</small></aside><main><header><div><p class="eyebrow">{{breadcrumb||'TOÀN CÔNG TY'}}</p><h1>{{titles[page]||'Farm 360'}}</h1></div><Button :loading="busy" @click="load">Cập nhật</Button></header><div class="scope-picker"><label>Công ty<select v-model="scope.company" @change="scope.farm='';updateScope()"><option value="">Tất cả công ty</option><option v-for="c in companies" :key="c">{{c}}</option></select></label><label>Nông trường<select v-model="scope.farm" @change="scope.block='';scope.plot='';updateScope()"><option value="">Tất cả nông trường</option><option v-for="f in farms" :key="f.name" :value="f.name">{{f.farm_name||f.name}}</option></select></label><label>Ngày<input type="date" v-model="scope.date" @change="scope.from_date='';scope.to_date='';updateScope()"/></label><label v-if="page==='reports'||page==='plans'">Từ ngày<input type="date" v-model="scope.from_date" @change="updateScope"/></label><label v-if="page==='reports'||page==='plans'">Đến ngày<input type="date" v-model="scope.to_date" @change="updateScope"/></label></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="busy" class="muted">Đang đọc số liệu…</p>
<section v-if="page==='today'"><div class="kpi-grid"><button v-for="card in cards" :key="card.label" class="kpi" @click="go(card.route)"><span>{{card.label}}</span><strong>{{fmt(card.value)}}</strong><small>{{card.unit}} ↗</small></button></div><section class="panel"><h2>Điểm cần xử lý</h2><div v-for="f in summary" :key="f.farm" class="farm-summary"><button class="text-link" @click="go('farm/'+encodeURIComponent(f.farm),{farm:f.farm})">{{f.farm}} ↗</button><span v-for="alert in f.alerts" :key="alert.kind" class="alert-chip">{{alert.kind}} · {{fmt(alert.value)}}</span><span v-if="!f.alerts.length" class="muted">Không có cảnh báo theo ngưỡng cấu hình.</span></div></section><section class="panel"><h2>Công việc ngày</h2><OpsList :rows="tasks" :columns="['farm','farm_plot','work_name','planned_qty','uom','completed_qty','required_workdays','allocated_workdays','status']" @open="go('work',{farm:$event.farm})"/></section><section class="panel"><h2>Khả năng cung ứng</h2><OpsList :rows="data?.forecast||[]" :columns="['farm','period_start_date','item','packed_forecast_kg','materialized_qty_kg','committed_qty_kg','available_to_promise_kg']" @open="edit('Harvest Forecast',$event.name)"/></section></section>
<section v-else-if="page==='reports'" class="panel"><h2>Dự thu trước thu 8 / 4 / 2 / 1 tuần</h2><p class="muted">Chỉ tính sai lệch khi nguồn thực tế đã nhận, QC, đóng gói và ghi kho đầy đủ.</p><OpsList :rows="data?.rows||[]" :columns="['farm','farm_plot','crop_cycle','horizon_weeks','forecast_kg','actual_kg','absolute_error_kg','signed_error_kg','change_kg','status']" @open="edit('Harvest Forecast',$event.forecast)"/><div class="kpi-grid"><div v-for="(metric,horizon) in data?.metrics||{}" :key="horizon" class="kpi"><span>{{horizon}} tuần</span><pre>{{JSON.stringify(metric,null,2)}}</pre></div></div><h2>Năng suất theo người / đội và loại công việc</h2><OpsList :rows="productivity?.rows||[]" :columns="['farm','work_type','employee','work_team','uom','completed_qty','actual_workdays','quantity_per_workday']"/><p class="muted">{{productivity?.unattributed?.length||0}} phiếu chỉ có số tổng; cần ghi thực tế theo người/đội để tính năng suất.</p><h2>Đề xuất hiệu chuẩn từ thực tế</h2><div class="schema-grid"><label>Profile gốc<input v-model="extra.base_profile"/></label><label>Vụ mẫu<input v-model="extra.crop_cycle"/></label><label>Mẫu từ<input type="date" v-model="extra.sample_from"/></label><label>Mẫu đến<input type="date" v-model="extra.sample_to"/></label><label>Hiệu lực từ<input type="date" v-model="extra.valid_from"/></label><label>Hiệu lực đến<input type="date" v-model="extra.valid_to"/></label></div><Button @click="command('lotus_farm.learning.create_calibrated_profile',{base_profile:extra.base_profile,crop_cycle:extra.crop_cycle,from_date:extra.sample_from,to_date:extra.sample_to,valid_from:extra.valid_from,valid_to:extra.valid_to})">Tạo Harvest Profile nháp</Button><Button @click="command('lotus_farm.learning.create_calibrated_packout',{base_profile:extra.base_profile,crop_cycle:extra.crop_cycle,from_date:extra.sample_from,to_date:extra.sample_to,valid_from:extra.valid_from,valid_to:extra.valid_to})">Tạo Packout Profile nháp</Button><h2>Tiến độ giao hàng</h2><p v-if="!scope.farm" class="muted">Chọn một nông trường để xem đơn đã giao, còn phải giao và phần đã giữ nguồn.</p><OpsList v-else :rows="delivery" :columns="['sales_order','item','ordered_kg','delivered_kg','remaining_demand_kg','state']"/></section>
<section v-else-if="page==='trace'" class="panel"><h2>Truy xuất nguồn gốc</h2><div class="schema-grid"><label>Loại<select v-model="extra.trace_kind"><option>Harvest Lot</option><option>Packout Run</option><option>Item</option><option>Farm Plot</option></select></label><label>Mã cần tìm<input v-model="extra.trace_query" @keyup.enter="traceSearch"/></label><label v-if="extra.trace_kind==='Item'">Batch (không bắt buộc)<input v-model="extra.trace_batch"/></label></div><Button @click="traceSearch">Truy xuất</Button><template v-if="trace?.kind==='Harvest Lot'"><OpsList :rows="trace.result.sources||[]" :columns="['farm','farm_block','farm_plot','crop_cycle','harvest_actual','contributed_kg']"/><OpsList :rows="trace.result.qc||[]" :columns="['name','received_kg','accepted_kg','rejected_kg']"/><OpsList :rows="trace.result.packout||[]" :columns="['name','packing_date','stock_entry']"/></template><template v-else-if="trace?.kind==='Packout Run'"><OpsList :rows="trace.result.sources||[]" :columns="['farm','farm_block','farm_plot','crop_cycle','harvest_lot','harvest_actual','fraction']"/><OpsList :rows="trace.result.outputs||[]" :columns="['item','batch','net_kg','output_type','grade','market']"/></template><template v-else-if="trace?.kind==='Item'"><article v-for="run in trace.result||[]" :key="run.packout" class="farm-summary"><Button @click="edit('Packout Run',run.packout)">{{run.packout}}</Button><span>{{run.farm}} · {{run.packing_date}} · {{run.stock_entry||'chưa ghi kho'}}</span></article><p v-if="trace&&!trace.result?.length" class="empty">Không tìm thấy thành phẩm phù hợp trong phạm vi được phép xem.</p></template><template v-else-if="trace?.kind==='Farm Plot'"><OpsList :rows="trace.result.events||[]" :columns="['date','doctype','name','crop_cycle']"/><OpsList :rows="trace.result.forecasts||[]" :columns="['name','supply_state','period_start_date','period_end_date','packed_forecast_kg']"/></template></section>
<section v-else-if="page==='map'" class="panel"><h2>Bản đồ thửa đã duyệt</h2><p v-if="!scope.farm" class="notice">Chọn một nông trường để xem ranh giới thửa.</p><PlotMap v-else :collection="mapData" @open="go('plot/'+encodeURIComponent($event),{plot:$event})"/></section>
<section v-else-if="page==='admin/settings'" class="panel"><div class="section-title"><div><h2>Cấu hình Lotus</h2><p class="muted">Các ngưỡng và hệ số phải do vận hành duyệt; ứng dụng không tự đoán số.</p></div><Button v-if="settingsSchema?.permissions?.write" :loading="dialogBusy" @click="saveSettings">Lưu cấu hình</Button></div><SchemaForm v-if="settingsSchema&&settingsDoc" :schema="settingsSchema" :model="settingsDoc" :scope="scope" :readonly="!settingsSchema.permissions.write"/></section>
<section v-else-if="page==='farms'||/^(farm|block)\//.test(page)" class="panel"><div class="section-title"><h2>{{page==='farms'?'Nông trường':page.startsWith('farm/')?'Lô trong nông trường':'Thửa trong lô'}}</h2><Button @click="edit(page==='farms'?'Farm':page.startsWith('farm/')?'Farm Block':'Farm Plot',null,{farm:scope.farm,farm_block:scope.block})">Thêm</Button></div><OpsList :rows="tree.rows||[]" :columns="tree.columns||[]" @open="openHierarchy"/><div class="pagination"><Button :disabled="!start" @click="pageMore(-50)">Trước</Button><Button :disabled="!tree.has_more" @click="pageMore(50)">Tiếp</Button></div><Button v-if="page!=='farms'" @click="go('work')">Việc trong phạm vi này</Button><Button v-if="page!=='farms'" @click="go('plans')">Dự thu / sản lượng</Button></section>
<section v-else-if="page.startsWith('plot/')"><section class="panel"><h2>{{data?.plot}} · {{data?.farm}} / {{data?.block}}</h2><OpsList :rows="data?.cycles||[]" :columns="['name','cycle_no','status','planting_date','variety']" @open="edit('Crop Cycle',$event.name)"/><div class="tabs"><button v-for="tab in tabs" :key="tab" :class="{active:tab===farmTab}" @click="farmTab=tab">{{tab}}</button></div><div v-if="farmTab==='Sản lượng'"><OpsList :rows="data?.forecasts||[]" :columns="['name','supply_state','period_start_date','period_end_date','packed_forecast_kg']" @open="edit('Harvest Forecast',$event.name)"/></div><div v-else class="timeline"><button v-for="event in (data?.events||[]).filter(e=>farmTab==='Công việc'?['Planting Event','Sucker Selection Batch','Bunch Operation','Daily Work Result','Fruit Measurement','Harvest Actual','Harvest Lot','Packout Run','Cycle Closing Report'].includes(e.doctype):farmTab==='Tổn thất'?['Bunch Cancellation','Disease Observation'].includes(e.doctype):farmTab==='Vật tư'?e.doctype==='Material Consumption':farmTab==='Nhân sự'?e.doctype==='Labor Allocation':farmTab==='QC'?e.doctype==='Incoming Quality Inspection':true)" :key="event.name" @click="edit(event.doctype,event.name)"><time>{{event.date}}</time><strong>{{docLabel(event.doctype)}}</strong><span>{{event.name}} ↗</span></button><p v-if="farmTab==='Ảnh'" class="muted">Mở sự kiện để xem chứng cứ ảnh/GPS đã ghi.</p><p v-if="farmTab==='Lịch sử thay đổi'" class="muted">Mở chứng từ và chọn Lịch sử để xem trước/sau, người sửa và lý do.</p></div></section></section>
<section v-else><div class="view-controls"><select v-model="doctype" @change="typeChanged"><option v-for="t in types" :key="t">{{docLabel(t)}}</option></select><input v-model="search" placeholder="Tìm mã phiếu…" @keyup.enter="start=0;load()"/><select v-model="sort" @change="load"><option value="modified desc">Mới cập nhật</option><option value="modified asc">Cũ nhất</option><option value="name asc">Mã tăng dần</option></select><Button v-if="session.creatable[doctype]!==false" @click="edit(doctype)">Thêm phiếu</Button><Button v-if="key==='work'" @click="scope.view=scope.view==='board'?'list':'board';updateScope()">{{scope.view==='board'?'Danh sách':'Bảng việc'}}</Button></div>
<section v-if="key==='work'&&overview" class="panel"><div class="section-title"><h2>Việc tại {{scope.farm}}</h2><Button @click="command('lotus_farm.field.make_suggested_plan',{farm:scope.farm,posting_date:scope.date})">Gợi ý kế hoạch đến hạn</Button></div><div :class="scope.view==='board'?'kanban':'work-list'"><section v-for="state in (scope.view==='board'?['Planned','Ready','In Progress','Blocked','Completed']:['Tất cả'])" :key="state"><h3 v-if="scope.view==='board'">{{stateLabel(state)}}</h3><article v-for="task in overview.tasks.filter(t=>state==='Tất cả'||t.status===state).filter(t=>(!scope.block||t.farm_block===scope.block)&&(!scope.plot||t.farm_plot===scope.plot))" :key="task.line" class="work-card"><div class="section-title"><strong>{{task.work_name||task.work_type}}</strong><span class="pill">{{stateLabel(task.status)}}</span></div><button class="text-link" @click="go('plot/'+encodeURIComponent(task.farm_plot),{plot:task.farm_plot})">{{task.farm_plot}} · {{task.crop_cycle}}</button><p>{{fmt(task.completed_qty)}} / {{fmt(task.planned_qty)}} {{task.uom}}</p><p class="muted">Công: {{fmt(task.allocated_workdays)}} / {{fmt(task.required_workdays)}} · {{task.work_team||task.responsible||'Chưa gán người phụ trách'}}</p><p class="muted">{{task.start_at||scope.date}} → {{task.due_at||scope.date}}</p><p v-if="task.blocked_reason" class="error">{{task.blocked_reason}}</p><div v-if="!task.result" class="actions"><Button v-if="['Planned','Blocked'].includes(task.status)" @click="transition(task,'Ready')">Sẵn sàng</Button><Button v-if="['Ready','Blocked'].includes(task.status)" @click="transition(task,'In Progress')">Bắt đầu</Button><Button @click="reason='';workDialog={...task,blocking:true}">Bị chặn</Button><Button @click="complete(task)">Ghi kết quả</Button><Button @click="edit('Labor Allocation',null,{work_plan:task.plan,work_plan_line:task.line,farm_block:task.farm_block,farm_plot:task.farm_plot,crop_cycle:task.crop_cycle,sucker_selection_batch:task.cohort})">Gán công</Button></div><Button v-else @click="edit('Daily Work Result',task.result)">Mở kết quả</Button></article></section></div></section>
<section v-if="key==='labor'&&overview" class="panel"><h2>Cần / có mặt / đã gán</h2><OpsList :rows="laborMatrix(overview.tasks,overview.labor)" :columns="['name','required','present','absent','allocated','gap','allocation_gap']"/><h3>Employee / Attendance ERP</h3><p class="muted">{{staff?.note}}</p><OpsList :rows="staff?.employees||[]" :columns="['employee','employee_name','attendance_known','remaining_workdays']"/></section>
<section v-if="key==='materials'&&material" class="panel"><h2>Nhu cầu còn lại và tồn khả dụng ERP</h2><p v-if="material.note" class="notice">{{material.note}}</p><OpsList :rows="material.rows" :columns="['item','uom','required_qty','actual_qty','available_qty','shortage_qty']"/><h3>Thực dùng so với định mức cho khối lượng đã làm</h3><OpsList :rows="material.usage" :columns="['requirement','item','uom','planned_qty','expected_for_actual','used_qty','variance_qty']" @open="edit('Material Requirement',$event.requirement)"/></section>
<section v-if="key==='incoming-qc'&&qc" class="panel"><h2>Ma trận lỗi đầu vào · kg</h2><div class="table-scroll"><table><thead><tr><th>Nguyên nhân</th><th v-for="lot in qc.lots" :key="lot.name">{{lot.name}}</th></tr></thead><tbody><tr v-for="defect in qc.defects" :key="defect.name"><th>{{defect.label}}</th><td v-for="lot in qc.lots" :key="lot.name"><button class="text-link" @click="showTrace('Harvest Lot',lot.name)">{{fmt(qc.cells.filter(c=>c.lot===lot.name&&c.defect===defect.name).reduce((n,c)=>n+c.weight_kg,0))}}</button></td></tr></tbody></table></div></section>
<section v-if="losses" class="panel"><h2>Hủy theo nông trường / lô / nguyên nhân</h2><OpsList :rows="losses.by_reason" :columns="['farm','farm_block','reason','bunch_qty']"/></section>
<section v-if="key==='daily-close'&&!scope.farm&&data" class="panel"><h2>Trạng thái chốt theo nông trường</h2><OpsList :rows="data.farms" :columns="['farm','closed','unclosed_dates']" @open="go('daily-close',{farm:$event.farm})"/></section>
<section v-if="key==='daily-close'&&scope.farm" class="panel"><h2>Kiểm tra trước chốt</h2><Button @click="closePreview">Xem đối soát</Button><OpsList v-if="preview" :rows="preview" :columns="['check_code','status','message','reference_doctype','reference_name']" @open="$event.reference_name&&edit($event.reference_doctype,$event.reference_name)"/><Button v-if="preview&&!preview.some(c=>c.status==='Block')" @click="edit('Daily Production Close')">Tạo phiếu chốt ngày</Button></section>
<section class="panel"><OpsList :rows="list.rows" :columns="list.columns" :loading="busy" @open="edit(doctype,$event.name)"/><div class="pagination"><Button :disabled="!start" @click="pageMore(-50)">Trước</Button><span>{{list.rows.length?`${start+1}–${start+list.rows.length}`:'0 bản ghi'}}</span><Button :disabled="!list.has_more" @click="pageMore(50)">Tiếp</Button></div></section></section>
</main></div>
<div v-if="editor&&schema" class="modal-backdrop"><section class="document-dialog" role="dialog" aria-modal="true" :aria-label="editor.doctype"><header><div><p class="eyebrow">{{editor.name||'PHIẾU MỚI'}} · {{['Nháp','Đã nộp','Đã hủy'][editor.docstatus||0]}}</p><h2>{{docLabel(editor.doctype)}}</h2></div><Button @click="editor=null;audit=null;shift=null">Đóng</Button></header><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><Button v-if="!editor.name&&schema.capture_fields?.length" :loading="dialogBusy" @click="sendField">Gửi hiện trường</Button><Button v-if="!editor.name&&schema.capture_fields?.length" @click="queueEditor">Lưu offline</Button><Button v-if="(!editor.name||editor.docstatus===0)&&(editor.name?schema.permissions.write:schema.permissions.create)" :loading="dialogBusy" @click="save">Lưu nháp</Button><Button v-if="editor.docstatus===0&&schema.is_submittable&&schema.permissions.submit" :loading="dialogBusy" @click="action('submit')">Nộp / duyệt</Button><Button v-if="editor.docstatus===1&&schema.permissions.cancel" @click="action('cancel')">Hủy / mở lại</Button><Button v-if="editor.docstatus===2&&schema.permissions.amend" @click="action('amend')">Tạo bản sửa</Button><Button v-if="editor.name" @click="showAudit">Lịch sử</Button><Button v-if="['Harvest Lot','Packout Run'].includes(editor.doctype)&&editor.name" @click="showTrace(editor.doctype,editor.name)">Truy nguồn</Button><Button v-if="editor.doctype==='Harvest Lot'&&editor.name" @click="showQR">QR lô thu</Button><a v-if="editor.name" :href="'/app/'+editor.doctype.toLowerCase().replaceAll(' ','-')+'/'+encodeURIComponent(editor.name)" target="_blank">Mở ERP ↗</a></div><label>Lý do hủy / sửa / mở lại<textarea v-model="reason" rows="2"/></label>
<div v-if="shift"><div class="tabs"><button v-for="tab in ['General','Labor','Incoming','Incoming QC','Preprocessing','Packout','Material Recovery','Secondary Product','Reconciliation']" :key="tab" :class="{active:tab===shiftTab}" @click="shiftTab=tab">{{stateLabel(tab)}}</button></div><div v-if="shiftTab==='Labor'"><OpsList :rows="shift.shift.labor" :columns="['employee','role_in_shift','workdays']"/></div><div v-else-if="shiftTab==='Preprocessing'||shiftTab==='Incoming'"><OpsList :rows="shift.shift.preprocessing" :columns="['harvest_lot','processed_bunches','processed_kg','started_at','ended_at']" @open="showTrace('Harvest Lot',$event.harvest_lot)"/></div><div v-else-if="shiftTab==='Packout'"><Button @click="edit('Packout Run',null,{packhouse_shift:shift.shift.name})">Thêm đợt đóng gói</Button><OpsList :rows="shift.runs" :columns="['name','docstatus','stock_status']" @open="edit('Packout Run',$event.name)"/></div><div v-else-if="shiftTab==='Material Recovery'"><Button @click="edit('Material Recovery',null,{packhouse_shift:shift.shift.name})">Ghi thu hồi</Button><OpsList :rows="shift.recovery" :columns="['name','consumption','recovered_qty','stock_entry','docstatus']" @open="edit('Material Recovery',$event.name)"/></div><div v-else-if="shiftTab==='Secondary Product'"><Button @click="edit('Secondary Product Movement',null,{packhouse_shift:shift.shift.name})">Ghi phụ phẩm</Button><OpsList :rows="shift.secondary" :columns="['name','item','quantity_kg','stock_entry','docstatus']" @open="edit('Secondary Product Movement',$event.name)"/></div><div v-else-if="shiftTab==='Reconciliation'" class="kpi-grid"><div v-for="field in ['input_kg','finished_kg','secondary_kg','loss_kg','cartons','packout_percent']" :key="field" class="kpi"><span>{{label(field)}}</span><strong>{{fmt(shift[field])}}</strong></div></div><Button v-else-if="shiftTab==='Incoming QC'" @click="editor=null;go('incoming-qc')">Mở ma trận lỗi và QC</Button></div>
<section v-if="!editor.name&&schema.capture_fields?.length" class="panel"><h3>Chứng cứ hiện trường</h3><div class="actions"><Button @click="locate">Lấy GPS</Button><span class="muted">{{fieldEvidence.latitude==null?'Chưa lấy vị trí':`${fieldEvidence.latitude.toFixed(6)}, ${fieldEvidence.longitude.toFixed(6)} · ±${Math.round(fieldEvidence.gps_accuracy_m||0)} m`}}</span></div><label>Ảnh<input type="file" accept="image/*" capture="environment" @change="fieldEvidence.photo=$event.target.files[0]||null"/></label><p class="muted">Lưu offline giữ nguyên event ID, ảnh và tài khoản. Máy chủ vẫn kiểm quyền, ngày và chống gửi trùng khi đồng bộ.</p></section><SchemaForm :schema="schema" :model="editor" :scope="scope" :readonly="editor.docstatus>0"/>
<section v-if="qr" class="panel"><h3>QR lô thu</h3><img :src="qr.image" :alt="'QR '+qr.harvest_lot" style="width:220px;max-width:100%"/><p><a :href="qr.url" target="_blank">Mở nguồn lô thu ↗</a></p></section><section v-if="evidence" class="panel"><h3>Chứng cứ hiện trường</h3><p>{{evidence.captured_by}} · {{evidence.captured_at}} · GPS {{evidence.latitude}}, {{evidence.longitude}} · ± {{evidence.gps_accuracy_m}} m</p><img v-if="evidence.photo" :src="evidence.photo" alt="Ảnh chứng cứ hiện trường" style="max-width:100%;max-height:350px"/><a :href="'/app/field-capture/'+editor.field_capture" target="_blank">Ảnh · GPS · thời điểm ghi ↗</a></section>
<section v-if="editor.name&&editor.doctype==='Harvest Forecast'" class="panel"><h3>Cam kết bán và chuyển sang hàng kho</h3><div class="schema-grid"><label>Đơn bán ERP<input v-model="extra.sales_order" @change="consoleAPI('order_lines',{sales_order:extra.sales_order}).then(r=>orderLines=r).catch(e=>error=e.message)"/></label><label>Dòng sản phẩm<select v-model="extra.sales_order_item"><option value="">Chọn dòng đơn</option><option v-for="line in orderLines" :key="line.name" :value="line.name">{{line.item}} · {{line.qty}} · {{line.delivery_date}}</option></select></label><label>Khối lượng giữ (kg)<input type="number" min="0" step="any" v-model.number="extra.quantity"/></label><label>Phiếu giữ hàng kho ERP<input v-model="extra.stock_reservation"/></label></div><Button @click="command('lotus_farm.allocations.reserve',{forecast:editor.name,sales_order:extra.sales_order,sales_order_item:extra.sales_order_item,qty_kg:extra.quantity,client_event_id:newEventID()})">Giữ phần dự thu</Button><div v-for="allocation in editor.allocations||[]" :key="allocation.name" class="farm-summary"><span>{{allocation.sales_order}} · {{allocation.item}} · {{allocation.reserved_qty_kg}} kg · {{allocation.allocation_state}}</span><Button v-if="allocation.allocation_state==='Reserved'" @click="command('lotus_farm.allocations.release',{forecast:editor.name,allocation:allocation.name})">Bỏ giữ dự thu</Button><Button v-if="allocation.allocation_state==='Reserved'" @click="command('lotus_farm.stock_bridge.link_stock_reservation',{forecast:editor.name,allocation:allocation.name,stock_reservation:extra.stock_reservation,qty_kg:extra.quantity})">Chuyển phần đã có hàng kho</Button></div></section>
<section v-if="editor.name&&editor.doctype==='Supply Reconciliation'&&editor.state==='Approved'" class="panel"><Button @click="command('lotus_farm.reconciliation.execute',{reconciliation:editor.name})">Áp dụng đối soát đã duyệt</Button></section>
<section v-if="editor.name&&editor.doctype==='Daily Work Plan'" class="panel"><Button @click="command('lotus_farm.daily_api.create_requirements',{work_plan:editor.name})">Tính nhu cầu vật tư</Button></section>
<section v-if="editor.name&&editor.doctype==='Material Requirement'" class="panel"><h3>Cấp / mua vật tư ERPNext</h3><label>Kho<input v-model="extra.warehouse"/></label><label>Ngày cần<input type="date" v-model="extra.schedule_date"/></label><Button @click="command('lotus_farm.daily_api.create_material_request',{requirement:editor.name,warehouse:extra.warehouse,schedule_date:extra.schedule_date||scope.date})">Tạo đề nghị mua phần thiếu</Button><a href="/app/stock-entry/new-stock-entry" target="_blank">Tạo phiếu cấp/xuất ERP ↗</a><p class="muted">Ghi Material Consumption/Recovery theo dòng Stock Entry đã nộp.</p></section>
<section v-if="editor.name&&editor.doctype==='Packout Run'" class="panel"><Button @click="command('lotus_farm.stock_bridge.make_repack_entry',{packout:editor.name})">Tạo phiếu nhập thành phẩm ERP</Button></section>
<section v-if="editor.name&&editor.doctype==='Source Import Batch'" class="panel"><Button @click="command('lotus_farm.importing.preview_import',{batch:editor.name}).then(r=>importPreview=r)">Kiểm tra thử</Button><Button @click="command('lotus_farm.importing.import_rows',{batch:editor.name})">Tạo giao dịch nháp</Button><OpsList v-if="importPreview" :rows="importPreview" :columns="['row','status','target_doctype','error']"/></section>
<section v-if="editor.name&&editor.doctype==='Integration Task'" class="panel"><Button @click="command('lotus_farm.importing.run_task',{task:editor.name})">Chạy / thử lại nhập nguồn</Button></section>
<section v-if="editor.name&&editor.doctype==='Source File Registry'" class="panel"><label>Mapping đã duyệt<input v-model="extra.base_profile"/></label><label>File Excel nguồn<input type="file" accept=".xlsx" @change="uploadSource"/></label><p v-if="extra.file_url" class="notice">Đã tải file nguồn private.</p><Button @click="command('lotus_farm.importing.stage_workbook',{source_file:editor.name,mapping:extra.base_profile,farm:scope.farm,file_url:extra.file_url})">Tạo staging</Button></section>
<section v-if="audit" class="panel audit-drawer"><h3>Lịch sử thay đổi</h3><p>{{audit.owner}} · tạo {{audit.created}}</p><article v-for="version in audit.versions" :key="version.name"><strong>{{version.owner}} · {{version.creation}}</strong><table><thead><tr><th>Trường</th><th>Trước</th><th>Sau</th></tr></thead><tbody><tr v-for="change in changes(version)" :key="change[0]"><td>{{change[0]}}</td><td>{{change[1]}}</td><td>{{change[2]}}</td></tr></tbody></table><details><summary>Chi tiết bảng con</summary><pre>{{JSON.stringify(JSON.parse(version.data),null,2)}}</pre></details></article><article v-for="comment in audit.comments" :key="comment.creation"><strong>{{comment.owner}} · {{comment.creation}}</strong><p>{{comment.content.replace(/<[^>]*>/g,'')}}</p></article></section>
</section></div>
<div v-if="outboxOpen" class="modal-backdrop"><section class="small-dialog"><div class="section-title"><h2>Hàng chờ hiện trường</h2><Button @click="outboxOpen=false">Đóng</Button></div><p class="muted">Chỉ hiển thị bản của {{session.user}}.</p><div class="actions"><Button :disabled="!online" @click="syncOutbox">Đồng bộ</Button><Button @click="clearSentRows">Xóa bản đã gửi</Button></div><article v-for="row in outbox" :key="row.key" class="child-row"><strong>{{docLabel(row.event.target_doctype)}} · {{row.status}}</strong><p class="muted">{{row.created}} · {{row.event.client_event_id}}</p><p v-if="row.error" class="error">{{row.error}}</p><p v-if="row.result?.document">Máy chủ: {{row.result.document}}</p><Button v-if="row.status==='Error'&&online" @click="reconcileRow(row)">Kiểm tra máy chủ / bỏ bản sai</Button></article><p v-if="!outbox.length" class="empty">Không có bản ghi trong hàng chờ.</p></section></div><div v-if="workDialog" class="modal-backdrop"><section role="dialog" aria-modal="true" class="small-dialog"><h2>{{workDialog.blocking?'Lý do bị chặn':'Ghi kết quả'}} · {{workDialog.work_name||workDialog.work_type}}</h2><p v-if="error" class="error">{{error}}</p><template v-if="!workDialog.blocking"><label>Khối lượng thực tế · {{workDialog.uom}}<input type="number" min="0" step="any" v-model.number="workActual.quantity"/></label><label>Công thực tế<input type="number" min="0" step="any" v-model.number="workActual.days"/></label><label>Lý do chưa hoàn thành<textarea v-model="workActual.reason"/></label><section v-if="workDialog.allocations?.length"><h3>Phân bổ thực tế theo người / đội</h3><Button @click="workActual.attribution.push({allocation:workDialog.allocations[0].name,quantity:0,days:0})">Thêm người / đội</Button><div v-for="(row,index) in workActual.attribution" :key="index" class="child-row"><label>Người / đội<select v-model="row.allocation"><option v-for="allocation in workDialog.allocations" :key="allocation.name" :value="allocation.name">{{allocation.employee||allocation.work_team}} · {{allocation.allocated_workdays}} công</option></select></label><label>Khối lượng<input type="number" min="0" step="any" v-model.number="row.quantity"/></label><label>Công<input type="number" min="0" step="any" v-model.number="row.days"/></label><Button @click="workActual.attribution.splice(index,1)">Xóa dòng</Button></div><small class="muted">Tổng khối lượng và công từng dòng phải khớp kết quả. Không tự chia năng suất cho người khi chưa có số thực tế.</small></section><Button :loading="dialogBusy" @click="finish">Nộp kết quả</Button></template><template v-else><textarea v-model="reason"/><Button @click="transition(workDialog,'Blocked').then(()=>{if(!error)workDialog=null})">Lưu trạng thái</Button></template><Button @click="workDialog=null">Đóng</Button></section></div>
<div v-if="trace&&page!=='trace'" class="modal-backdrop"><section class="document-dialog" role="dialog" aria-modal="true"><header><h2>Truy nguồn</h2><Button @click="trace=null">Đóng</Button></header><OpsList :rows="trace.sources||[]" :columns="['company','farm','farm_block','farm_plot','crop_cycle','harvest_actual','contributed_kg','fraction']" @open="edit('Harvest Actual',$event.harvest_actual)"/><OpsList :rows="trace.qc||[]" :columns="['name','received_kg','accepted_kg','rejected_kg']" @open="edit('Incoming Quality Inspection',$event.name)"/><OpsList :rows="trace.outputs||[]" :columns="['item','batch','net_kg','output_type','grade','market']"/><Button v-for="run in trace.packout||[]" :key="run" @click="trace=null;edit('Packout Run',run)">{{run}}</Button><p class="muted">ID nguồn giữ nguyên; mở thửa hoặc chứng từ liên quan để xem lịch sử.</p><Button v-for="source in trace.sources||[]" :key="source.harvest_actual" @click="trace=null;go('plot/'+encodeURIComponent(source.farm_plot),{farm:source.farm,block:source.farm_block,plot:source.farm_plot})">{{source.farm_plot}} · {{source.harvest_actual}}</Button></section></div>
</FrappeUIProvider></template>
